"""Private observation plugin: forwarding streams and subprocess return values."""
import contextlib,functools,hashlib,io,json,os,subprocess,sys,threading
from pathlib import Path
_node=None
_lock=threading.Lock()
_original_run=None
_original_main=None

def emit(event):
    event['nodeid']=_node
    directory=Path(os.environ['INTEROP_RECORD_DIR']);directory.mkdir(exist_ok=True)
    name=hashlib.sha256((_node or 'session').encode()).hexdigest()[:20]+'.jsonl'
    with _lock:
        with (directory/name).open('a') as stream:stream.write(json.dumps(event,default=str)+'\n')

def text(value):
    if isinstance(value,bytes):return value.decode('utf-8',errors='replace')
    return value

class ForwardingStream:
    def __init__(self,original,capture):self.original,self.capture=original,capture
    def write(self,value):
        self.capture.write(value)
        return self.original.write(value)
    def flush(self):return self.original.flush()
    def __getattr__(self,name):return getattr(self.original,name)

def pytest_configure(config):
    global _original_run,_original_main
    from cbus_toolkit import cli
    _original_run=subprocess.run;_original_main=cli.main
    @functools.wraps(_original_run)
    def recorded_run(*args,**kwargs):
        argv=kwargs.get('args',args[0] if args else None)
        try:result=_original_run(*args,**kwargs)
        except BaseException as error:
            emit({'kind':'subprocess.run','argv':argv,'exit':getattr(error,'returncode',None),'stdout':text(getattr(error,'stdout',None)),'stderr':text(getattr(error,'stderr',None)),'exception':{'type':type(error).__name__,'message':str(error)}})
            raise
        emit({'kind':'subprocess.run','argv':argv,'exit':result.returncode,'stdout':text(result.stdout),'stderr':text(result.stderr)})
        return result
    @functools.wraps(_original_main)
    def recorded_main(*args,**kwargs):
        output,error=io.StringIO(),io.StringIO();result=None;exception=None
        try:
            with contextlib.redirect_stdout(ForwardingStream(sys.stdout,output)),contextlib.redirect_stderr(ForwardingStream(sys.stderr,error)):
                result=_original_main(*args,**kwargs)
            return result
        except BaseException as failure:
            exception={'type':type(failure).__name__,'message':str(failure)}
            raise
        finally:
            emit({'kind':'in-process-cli.main','argv':kwargs.get('argv',args[0] if args else None),'exit':result,'stdout':output.getvalue(),'stderr':error.getvalue(),'exception':exception})
    subprocess.run=recorded_run;cli.main=recorded_main

def pytest_runtest_setup(item):
    global _node
    _node=item.nodeid

def pytest_runtest_logreport(report):
    if report.when=='call':emit({'kind':'pytest-call','outcome':report.outcome})

def pytest_unconfigure(config):
    if _original_run is not None:subprocess.run=_original_run
    if _original_main is not None:
        from cbus_toolkit import cli
        cli.main=_original_main
